// This file is generated by AI.

// 资源类型探测: 通过文件头魔数 (magic bytes) 判断实际类型, 不只看扩展名。

import type { FileKind } from '../components/FileTree';

function ascii(bytes: Uint8Array, start: number, len: number): string {
  return String.fromCharCode(...bytes.subarray(start, start + len));
}

function looksLikeText(head: Uint8Array): boolean {
  if (head.length === 0) return true;
  let printable = 0;
  for (let i = 0; i < head.length; i++) {
    const b = head[i];
    if (b === 9 || b === 10 || b === 13 || (b >= 32 && b < 127) || b >= 0x80) printable++;
  }
  return printable / head.length >= 0.9;
}

/** 根据文件头判断资源类型; 无法识别时返回 null。 */
export function sniffKind(head: Uint8Array): FileKind | null {
  if (head.length >= 8 && head[0] === 0x89 && head[1] === 0x50 && head[2] === 0x4e && head[3] === 0x47) return 'image'; // PNG
  if (head.length >= 3 && head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff) return 'image'; // JPEG
  if (head.length >= 4 && ascii(head, 0, 4) === 'GIF8') return 'image';
  if (head.length >= 2 && ascii(head, 0, 2) === 'BM') return 'image'; // BMP
  if (head.length >= 12 && ascii(head, 0, 4) === 'RIFF' && ascii(head, 8, 4) === 'WEBP') return 'image'; // WebP
  if (head.length >= 12 && ascii(head, 0, 4) === 'RIFF' && ascii(head, 8, 4) === 'WAVE') return 'audio'; // WAV
  if (head.length >= 4 && ascii(head, 0, 4) === 'OggS') return 'audio'; // OGG
  if (head.length >= 4 && ascii(head, 0, 4) === 'fLaC') return 'audio'; // FLAC
  if (head.length >= 3 && ascii(head, 0, 3) === 'ID3') return 'audio'; // MP3 (ID3 标签)
  if (head.length >= 2 && head[0] === 0xff && (head[1] & 0xe0) === 0xe0) return 'audio'; // MP3 帧同步
  if (head.length >= 4 && head[0] === 0x1a && head[1] === 0x45 && head[2] === 0xdf && head[3] === 0xa3) return 'video'; // MKV/WebM
  if (head.length >= 12 && ascii(head, 4, 4) === 'ftyp') {
    const brand = ascii(head, 8, 4);
    return brand.startsWith('M4') ? 'audio' : 'video'; // M4A / MP4
  }
  // SVG 为文本, 但可作图片预览
  if (head.length >= 4 && /<svg[\s>]/i.test(ascii(head, 0, head.length))) return 'image';
  if (looksLikeText(head)) return 'text';
  return null;
}
